def _arm_prefill_decode_interval(self, batch: Optional[ScheduleBatch]) -> None:
        if self.prefill_decode_interval == 0 or batch is None:
            return

        # DP attention synchronizes this flag across ranks. This keeps every
        # rank on the same prefill/decode cadence even when only one rank has
        # local prefill work. Non-DP scheduling can use the local mode directly.
        is_extend = (
            batch.is_extend_in_batch
            if self.require_mlp_sync
            else batch.forward_mode.is_extend()
        )
        if is_extend:
            self._prefill_decode_interval_remaining = self.prefill_decode_interval

def master_decision(scheduler,batch,original,budget_ms,now=time.perf_counter):
    try:
        defer=original(scheduler,batch)
        remaining=scheduler._prefill_decode_interval_remaining
        entries=[]
        if budget_ms is not None and defer:
            entries=[getattr(getattr(req,'time_stats',None),'wait_queue_entry_time',None)
                     for req in scheduler.waiting_queue]
        decision,count,reason=limit_wait(defer,remaining,entries,
            now() if entries else None,budget_ms)
        return [int(decision),count,reason]
    except Exception:
        return [-1,0,3]
